import json, os
base = os.path.dirname(os.path.abspath(__file__))
outdir = os.path.join(base, "predictions")
os.makedirs(outdir, exist_ok=True)

def ly(text, basis, conf, cm, ru, dis, reason):
    return {"prediction_text": text, "basis": basis, "confidence": conf,
            "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": dis, "reason": reason}}
def bz(text, basis, conf):
    return {"prediction_text": text, "basis": basis, "confidence": conf,
            "trigger": {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}}

